package main

import (
	"bytes"
	"fmt"
)

const generatedHeader = `// SPDX-License-Identifier: Apache-2.0

// Code generated by public-gen. DO NOT EDIT.
`

// emitPublic writes the selected public types and conversion methods before formatting.
func emitPublic(m model) []byte {
	var out bytes.Buffer
	out.WriteString(generatedHeader)
	out.WriteString("\npackage v1\n\nimport (\n")
	if m.UsesTime {
		out.WriteString("metav1 \"k8s.io/apimachinery/pkg/apis/meta/v1\"\n")
	}
	if m.UsesUID {
		out.WriteString("\"k8s.io/apimachinery/pkg/types\"\n")
	}
	out.WriteString("\n\"github.com/dsx-ai-factory/nvke/management-engine/pkg/projection\"\n)\n")
	for _, r := range m.Resources {
		emitPublicResource(&out, r)
	}
	return out.Bytes()
}

// emitPublicResource writes one projected resource while retaining its source JSON tags.
func emitPublicResource(out *bytes.Buffer, r resourceModel) {
	fmt.Fprintf(out, "\n// %s reuses the complete approved spec/status of %s.\n", r.Public, r.Source)
	out.WriteString("// Only metadata is filtered automatically, by its explicit allowlist.\n")
	out.WriteString("// +kubebuilder:object:generate=false\n")
	fmt.Fprintf(out, "type %s struct {\n", r.Public)
	fmt.Fprintf(out, "Metadata %sMetadata `json:\"metadata\"`\n", r.Public)
	fmt.Fprintf(out, "Spec %s %s\n", r.Spec, r.SpecTag)
	if r.Status != "" {
		fmt.Fprintf(out, "Status %s %s\n", r.Status, r.StatusTag)
	}
	out.WriteString("}\n")
	fmt.Fprintf(out, "\n// %sMetadata contains only the metadata approved for this public resource.\n", r.Public)
	out.WriteString("// +kubebuilder:object:generate=false\n")
	fmt.Fprintf(out, "type %sMetadata struct {\n", r.Public)
	for _, field := range r.Fields {
		fmt.Fprintf(out, "%s %s `json:%q`\n", field.Name, field.Type, field.Tag)
	}
	out.WriteString("}\n")
	fmt.Fprintf(out, `
// Convert maps %s to its datastore representation using matching JSON names.
func (in %s) Convert() (%s, error) {
	return projection.JSON[%s](in)
}
`, r.Public, r.Public, r.Source, r.Source)
	fmt.Fprintf(out, `
// Convert exposes only the public fields of %s.
func (in %s) Convert() (%s, error) {
	return projection.JSON[%s](in)
}
`, r.Source, r.Source, r.Public, r.Public)
	if r.NeedsPublicValidation {
		out.WriteString("\n// Validate leaves schema checks to datastore admission. This resource adds no public rules.\n")
		fmt.Fprintf(out, "func (%s) Validate() error { return nil }\n", r.Public)
	}
	if r.NeedsSourceValidation {
		out.WriteString("\n// Validate leaves internal schema checks to datastore admission.\n")
		fmt.Fprintf(out, "func (%s) Validate() error { return nil }\n", r.Source)
	}
}

// emitRegistrations writes each resource's datastore binding and caller-selected operations.
func emitRegistrations(m model) []byte {
	var out bytes.Buffer
	out.WriteString(generatedHeader)
	fmt.Fprintf(&out, `
package publicapi

import (
	"k8s.io/apimachinery/pkg/runtime/schema"

	v1 %q
	"github.com/dsx-ai-factory/nvke/management-engine/pkg/resource"
)
`, m.SourceImport)
	for _, r := range m.Resources {
		fmt.Fprintf(
			&out,
			"\n// %s returns a registration for %s with the caller's selected operations.\n",
			r.Source,
			r.Public,
		)
		out.WriteString("// An empty selection enables no operations.\n")
		fmt.Fprintf(&out, "func %s(verbs ...resource.Operation) resource.Registration {\n", r.Source)
		fmt.Fprintf(
			&out,
			"return resource.NewRegistration[v1.%s, v1.%s](%q, resource.ResourceInfo{\n",
			r.Public,
			r.Source,
			r.Path,
		)
		fmt.Fprintf(&out, "GVK: schema.GroupVersionKind{Group: %q, Version: %q, Kind: %q},\n", r.Group, r.Version, r.Source)
		fmt.Fprintf(&out, "Resource: %q, Scope: resource.Scope(%q),\n", r.Resource, r.Scope)
		fmt.Fprintf(&out, "HasStatus: %t, Verbs: verbs,\n", r.HasStatus)
		out.WriteString("})\n}\n")
	}
	return out.Bytes()
}
